// CH-01, node: "BRAKE: can we afford this run?"
// Mode: Run Once for All Items
//
// Decides whether to spend money, and builds the Apify input if so.
//
// This node exists in this position - before the first live request, not
// after the first surprise bill - because of a specific lesson from the
// LinkedIn project's post-mortem:
//
//     "The budget goes in before the first live request, not after the
//      fourth bug. Brakes are not a later refinement."
//
// That project's hard cap was written on the night of the incident it would
// have prevented. Apify's free plan is $5 a month with no rollover and it
// BLOCKS runs at zero rather than warning first, so the failure mode here is
// a pipeline that silently stops producing leads on the 14th of the month
// and looks, from the outside, exactly like a pipeline that found nothing.

const rows = $input.all().map((i) => i.json);
const CFG = $('Config').first().json;

// No due target is the normal state most days: cooldown_hours is doing its
// job. That is the system idling correctly, not a fault, and it must not look
// like one in the report.
if (!rows.length) {
  return [{
    json: {
      go: false,
      reason: 'no target is due - every enabled market is still inside its cooldown window. ' +
              'This is the schedule working, not a failure.',
      quiet: true,
    },
  }];
}

const t = rows[0];

// --- the spend check -------------------------------------------------------
//
// TWO limits, and the run needs room under BOTH.
//
//   1. What Apify says is actually left this month. This is the truth, asked
//      live, and it is the one that matters. Our own place counter can only
//      ever under-estimate: Apify bills for the actor start and for each
//      filter applied per place as well as for the place itself, so a budget
//      expressed in places drifts below the real spend and would eventually
//      let a run start with nothing left to pay for it.
//
//   2. Our own monthly place cap in app_state. Kept as a deliberate ceiling
//      you can lower below the plan's - useful when the credit is shared with
//      something else, and it still works if the limits endpoint is down.
//
// Both fail CLOSED. A brake whose input is missing refuses.

// --- limit 1: live credit -------------------------------------------------
let creditRemainingUsd = null;
try {
  const lim = $('How much credit is left?').first().json.data;
  const usedUsd = Number(lim.current.monthlyUsageUsd);
  const maxUsd = Number(lim.limits.maxMonthlyUsageUsd);
  if (Number.isFinite(usedUsd) && Number.isFinite(maxUsd)) {
    creditRemainingUsd = maxUsd - usedUsd;
  }
} catch (e) {
  // Leaving it null is what makes the next block refuse. An unreachable
  // limits endpoint is not permission to spend.
}

if (creditRemainingUsd === null) {
  return [{
    json: {
      go: false,
      reason: 'could not read the Apify credit limit, so there is no way to know what a run ' +
              'would cost against what is left. Refusing rather than guessing. Check the ' +
              '"Apify token" credential and the How much credit is left? node.',
      quiet: false,
    },
  }];
}

// A reserve, because the per-place rate is not the whole bill. The actor start
// is $0.007 and each filter applied costs $0.001 per place, so a run that
// exactly exhausts the remaining dollars stops part-way through - which costs
// the same money and returns a partial, geographically biased slice of a city.
const perPlace = Number(CFG.apify_cost_per_place || 0.005);
const reserve = Number(CFG.apify_reserve_usd || 0.30);
const affordableByCredit = Math.floor(Math.max(0, creditRemainingUsd - reserve) / perPlace);

// --- limit 2: our own ceiling ---------------------------------------------
// The counter resets itself on month rollover in the same statement that
// increments it, so a stale month here means the counter has simply not been
// touched yet this month and reads as zero.
const sameMonth = t.spend_month === t.current_month;
const used = sameMonth ? Number(t.spend_places_scraped || 0) : 0;
const cap = Number(t.spend_monthly_cap || 0);

// A missing or zero cap does NOT mean "unlimited".
//
// An earlier version read `cap > 0 ? cap - used : Infinity`, so deleting the
// app_state row - or fat-fingering the JSON in it - switched the brake off
// entirely. That is precisely the shape of the mistake the sibling project
// made: "a bounce counter with nothing that sets it would have been a brake
// wired to nothing."
if (!Number.isFinite(cap) || cap <= 0) {
  return [{
    json: {
      go: false,
      reason: 'no Apify place cap is configured (app_state.apify_spend.monthly_place_cap ' +
              'is missing or zero). Refusing rather than spending without a ceiling. ' +
              'Set a number - a large one if you really want no cap of our own.',
      quiet: false,
    },
  }];
}

const affordableByCap = cap - used;
const remaining = Math.min(affordableByCredit, affordableByCap);
const binding = affordableByCredit <= affordableByCap ? 'Apify credit' : 'our own monthly cap';

if (remaining <= 0) {
  return [{
    json: {
      go: false,
      reason: `out of budget (${binding} is the limit). ` +
              `$${creditRemainingUsd.toFixed(2)} credit left, which buys about ` +
              `${affordableByCredit} places; our own cap allows ${affordableByCap} more ` +
              `(${used}/${cap} used in ${t.current_month}). No run started.`,
      // Routine once the month's budget is used - CH-07's digest is enough;
      // a Telegram message every 30 minutes was not.
      quiet: true,
    },
  }];
}

// Never ask for more than the budget can pay for. Asking for 150 with 40 left
// does not fail politely - it spends the 40 and stops mid-scrape, which costs
// the same and returns a partial, biased slice of the city.
const want = Math.min(Number(t.max_results || 100), remaining);

if (want < 10) {
  return [{
    json: {
      go: false,
      reason: `only ${remaining} places left in this month's cap - too few for a meaningful ` +
              `run, so nothing was started rather than half-scraping ${t.city || t.country}.`,
      // Routine once the month's budget is used - CH-07's digest is enough;
      // a Telegram message every 30 minutes was not.
      quiet: true,
    },
  }];
}

// --- build the Apify input -------------------------------------------------
//
// website: 'withoutWebsite' is the single most important line in this repo.
// It is the reason discovery is cheap: the actor returns only businesses whose
// Maps listing carries no website, so we pay for prospects rather than for a
// whole city we then throw 73% of away.
//
// It is emphatically NOT the answer on its own - a listing with no website
// field is a candidate, and CH-02 exists to find out whether it is true.
const input = {
  searchStringsArray: [t.niche_query],
  maxCrawledPlacesPerSearch: want,
  language: 'en',
  website: 'withoutWebsite',
  skipClosedPlaces: true,
  scrapeContacts: false,
};

// Location. A custom polygon wins over the free-text fields when one is set,
// because a city name is ambiguous in a way a polygon is not.
if (t.custom_geolocation) {
  input.customGeolocation = t.custom_geolocation;
} else {
  if (t.city) input.city = t.city;
  if (t.state) input.state = t.state;
  if (t.postal_code) input.postalCode = t.postal_code;

  // countryCode is an ENUM of lowercase ISO-2 codes, not a country name. An
  // earlier version passed "Norway" here, which is not in the enum - the run
  // would have searched with no country at all, and "beauty salon" unscoped is
  // a global search that would have spent the month's credit on results from
  // anywhere. Refusing is the only safe response to a missing code.
  if (!t.country_code) {
    return [{
      json: {
        go: false,
        reason: `target ${t.id} (${t.niche} / ${t.country}) has no country_code and no ` +
                `custom_geolocation. The scraper needs a lowercase ISO-2 code; without one ` +
                `the search would not be restricted to any country at all. No run started.`,
        quiet: false,
      },
    }];
  }
  input.countryCode = String(t.country_code).toLowerCase();
}

if (Array.isArray(t.category_filter) && t.category_filter.length) {
  input.categoryFilterWords = t.category_filter;
}

// placeMinimumStars is an enum of WORDS - 'four', 'fourAndHalf' - not a
// number. String(4.5) is not in the enum, so passing the rating straight
// through silently dropped the filter.
if (t.min_rating) {
  const STARS = {
    '2': 'two', '2.5': 'twoAndHalf',
    '3': 'three', '3.5': 'threeAndHalf',
    '4': 'four', '4.5': 'fourAndHalf',
  };
  const word = STARS[String(Number(t.min_rating))];
  // An unmappable value is left out rather than guessed at. Dropping a filter
  // costs a few extra places; sending an invalid enum fails the whole run.
  if (word) input.placeMinimumStars = word;
}

return [{
  json: {
    go: true,
    target_id: t.id,
    niche: t.niche,
    niche_query: t.niche_query,
    city: t.city,
    country: t.country,
    asked_for: want,
    budget_remaining: remaining,
    budget_binding: binding,
    credit_remaining_usd: Number(creditRemainingUsd.toFixed(2)),
    apify_input: input,
    // Carried through for the normaliser, which needs the target's fields and
    // should not have to query for them again.
    ...t,
  },
}];

// CH-01, node: "Normalise the business"
// Mode: Run Once for All Items
//
// Turns whatever the Apify actor happened to return into the shape the
// businesses table expects, and computes the three dedup keys.
//
// Two things here are defensive on purpose:
//
//   1. Field names. Apify's Maps actors do not agree with each other and do
//      not agree with their own previous versions. Every read goes through
//      pick(), which tries several spellings. The whole record is kept in
//      `raw` so a field that moves can be re-mapped later without re-scraping
//      and re-paying for it.
//
//   2. Accents. This project targets Norway, Spain, Portugal, Italy and the
//      UAE. "Frisør" and "frisor", "Peluquería" and "peluqueria" are the same
//      business, and a name key that does not fold them produces a duplicate
//      on every second Scandinavian salon. NFD-normalising before stripping
//      combining marks is what makes name_norm stable across sources — which
//      matters most at Stage B, where we match Google's spelling against
//      Overture's.

const CFG = $('Config').first().json;
const target = $('Pick one target').first().json;

// --- field access ----------------------------------------------------------
const pick = (o, ...keys) => {
  for (const k of keys) {
    const v = k.split('.').reduce((a, p) => (a == null ? a : a[p]), o);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return '';
};

// --- name normalisation ----------------------------------------------------
// Legal forms carry no identifying information and are written inconsistently
// across sources: "Salong Eksempel AS" in Google is often "Salong Eksempel" in
// Overture. Stripping them is what lets the two match.
const LEGAL = new Set([
  // Scandinavia
  'as', 'asa', 'ans', 'da', 'nuf', 'ab', 'hb', 'kb', 'aps', 'is', 'ks',
  // Southern Europe
  'sl', 'slu', 'sa', 'sau', 'lda', 'unipessoal', 'srl', 'srls', 'spa', 'snc', 'sas',
  // Gulf
  'llc', 'lc', 'fze', 'fzco', 'fzllc', 'dmcc', 'est', 'establishment',
  // Anglo
  'inc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'ulc', 'plc',
  // Generic filler
  'the', 'and', 'group', 'holdings', 'international',
]);

// Folds accents so that the same business matches across sources.
// NFD splits an accented letter into base + combining mark; the mark is
// then stripped by code point rather than by a literal character class,
// because this file is round-tripped through JSON on its way into n8n and
// a literal combining mark does not survive that reliably.
const COMBINING = /[̀-ͯ]/g;
// Letters that do NOT decompose under NFD and so must be mapped by hand.
// Norwegian and Danish alone make this non-optional: without it, every
// "Frisor" / "Frisør" pair is two businesses instead of one.
const FOLD = [
  [/ø/g, 'o'], [/Ø/g, 'o'],   // o-slash
  [/æ/g, 'ae'], [/Æ/g, 'ae'], // ae ligature
  [/å/g, 'a'], [/Å/g, 'a'],   // a-ring
  [/ß/g, 'ss'],                     // sharp s
  [/đ/g, 'd'], [/ł/g, 'l'],   // d-stroke, l-stroke
  [/œ/g, 'oe'], [/Œ/g, 'oe'], // oe ligature - matters for Quebec
  [/þ/g, 'th'], [/ð/g, 'd'],  // thorn, eth
];
const deaccent = (s) => {
  let t = String(s || '').normalize('NFD').replace(COMBINING, '');
  for (const [re, to] of FOLD) t = t.replace(re, to);
  return t;
};

const normaliseName = (raw) => {
  const words = deaccent(raw)
    .toLowerCase()
    // Dots are CLOSED UP, not turned into spaces. Southern-European legal
    // forms are written "S.L.", "S.p.A.", "A/S" — splitting on the dots turns
    // one legal form into several single letters, which then survive the
    // LEGAL filter because "s" and "l" are not "sl". That produced
    // "peluqueria sol s l" where Overture holds "peluqueria sol", so the two
    // never matched and Stage B silently stopped catching Spanish
    // false positives.
    .replace(/[.\/]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter((w) => !LEGAL.has(w))
    // A bare single letter left over from an abbreviation is noise, never a
    // distinguishing feature of a business name.
    .filter((w) => w.length > 1 || /[0-9]/.test(w));
  return words.join(' ').trim();
};

// --- phone -----------------------------------------------------------------
// E.164 is the strongest dedup key there is: two listings that share a phone
// number are the same business, whatever they call themselves.
const DIAL = {
  'norway': '47', 'sweden': '46', 'denmark': '45', 'finland': '358',
  'united arab emirates': '971', 'qatar': '974', 'saudi arabia': '966',
  'spain': '34', 'portugal': '351', 'italy': '39', 'greece': '30',
  'canada': '1', 'united states': '1', 'pakistan': '92',
};

const toE164 = (raw, country) => {
  let s = String(raw || '').trim();
  if (!s) return '';
  const hasPlus = s.startsWith('+');
  s = s.replace(/[^\d]/g, '');
  if (!s) return '';
  if (hasPlus) return '+' + s;
  if (s.startsWith('00')) return '+' + s.slice(2);

  const cc = DIAL[String(country || '').toLowerCase()];
  if (!cc) return '';                       // unknown country: refuse to guess
  // A national number conventionally carries a trunk 0 that E.164 drops.
  // Getting this wrong makes every Italian number a non-match, so Italy is
  // the exception worth knowing: it KEEPS its leading 0 on landlines.
  if (s.startsWith(cc) && s.length > String(cc).length + 5) return '+' + s;
  if (s.startsWith('0') && cc !== '39') s = s.slice(1);
  return '+' + cc + s;
};

// --- geohash ---------------------------------------------------------------
// Precision 7 is roughly a 153m x 153m cell. Chosen because it is about the
// size of a city block: two listings of the same salon rarely differ by more
// than a few metres, and two DIFFERENT salons with the same normalised name
// inside one block is rare enough to accept as a collision.
//
// Written out rather than imported because an n8n Code node has no packages.
const B32 = '0123456789bcdefghjkmnpqrstuvwxyz';
const geohash = (lat, lon, precision) => {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return '';
  // Null island. pick() returns '' for a missing field and Number('') is 0, so
  // a business with no coordinates lands at 0,0 and hashes to 7zzzzzz - the
  // SAME cell as every other business with no coordinates. Combined with
  // name_norm that is a dedup key which starts merging unrelated businesses,
  // and a Stage B cross-check that matches them against each other. An
  // absent coordinate has to stay absent.
  if (lat === 0 && lon === 0) return '';
  let latMin = -90, latMax = 90, lonMin = -180, lonMax = 180;
  let hash = '', bits = 0, ch = 0, even = true;
  while (hash.length < precision) {
    if (even) {
      const mid = (lonMin + lonMax) / 2;
      if (lon > mid) { ch = (ch << 1) + 1; lonMin = mid; } else { ch = ch << 1; lonMax = mid; }
    } else {
      const mid = (latMin + latMax) / 2;
      if (lat > mid) { ch = (ch << 1) + 1; latMin = mid; } else { ch = ch << 1; latMax = mid; }
    }
    even = !even;
    if (++bits === 5) { hash += B32[ch]; bits = 0; ch = 0; }
  }
  return hash;
};

// --- social profiles -------------------------------------------------------
const SOCIAL_KEYS = [
  ['facebook', 'facebooks', 'facebookUrl'],
  ['instagram', 'instagrams', 'instagramUrl'],
  ['linkedin', 'linkedIns', 'linkedinUrl'],
  ['twitter', 'twitters', 'twitterUrl'],
  ['tiktok', 'tiktoks', 'tiktokUrl'],
  ['youtube', 'youtubes', 'youtubeUrl'],
];

const collectSocials = (p) => {
  const out = {};
  for (const [name, ...aliases] of SOCIAL_KEYS) {
    const v = pick(p, name, ...aliases);
    if (!v) continue;
    out[name] = Array.isArray(v) ? v[0] : v;
  }
  return out;
};

// ---------------------------------------------------------------------------

const rows = $input.all().map((i) => i.json);

// An empty result is ambiguous — it can mean "the actor returned nothing" or
// "the HTTP node handed us the wrong shape" — and the two need different
// fixes. Saying which it is here saves the half hour of reading execution
// output that the job-hunt repo spent learning to do this.
if (!rows.length) {
  throw new Error(
    `Apify returned 0 items for "${target.niche_query}" in ${target.city || target.country}. ` +
    `Either the search genuinely has no results without websites, or the dataset ` +
    `id was wrong. Check the run in the Apify console before changing this node.`
  );
}

const out = [];
const seen = new Set();
let skippedNoId = 0;
let skippedClosed = 0;

for (const p of rows) {
  const placeId = String(pick(p, 'placeId', 'place_id', 'placeID', 'cid', 'fid') || '').trim();
  if (!placeId) { skippedNoId++; continue; }
  if (seen.has(placeId)) continue;             // within-batch dedup
  seen.add(placeId);

  const closed = Boolean(pick(p, 'permanentlyClosed', 'permanently_closed') === true);
  if (closed) { skippedClosed++; continue; }   // a closed business is not a lead

  const name = String(pick(p, 'title', 'name', 'placeName') || '').trim();
  if (!name) { skippedNoId++; continue; }

  const country = String(pick(p, 'countryCode', 'country') || target.country || '');
  // Number('') is 0, so an absent coordinate has to be rejected before the
  // conversion rather than after it.
  const numOrNull = (v) => {
    if (v === '' || v === null || v === undefined) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };
  const lat = numOrNull(pick(p, 'location.lat', 'latitude', 'lat'));
  const lon = numOrNull(pick(p, 'location.lng', 'location.lon', 'longitude', 'lng', 'lon'));
  const phoneRaw = String(pick(p, 'phone', 'phoneUnformatted', 'internationalPhoneNumber') || '');

  const categories = []
    .concat(pick(p, 'categories', 'categoryName') || [])
    .flat()
    .filter(Boolean)
    .map(String);

  out.push({
    json: {
      google_place_id: placeId,
      search_target_id: target.id,
      niche: target.niche,

      name,
      name_norm: normaliseName(name),
      category_primary: String(pick(p, 'categoryName', 'category') || categories[0] || ''),
      categories,

      address: String(pick(p, 'address', 'formattedAddress') || ''),
      street: String(pick(p, 'street') || ''),
      city: String(pick(p, 'city', 'locality') || target.city || ''),
      state: String(pick(p, 'state', 'region') || target.state || ''),
      country: target.country,
      country_code: String(pick(p, 'countryCode') || ''),
      postal_code: String(pick(p, 'postalCode', 'zip') || ''),
      lat,
      lon,
      geohash7: geohash(lat, lon, 7),

      phone_raw: phoneRaw,
      phone_e164: toE164(phoneRaw, country) || toE164(phoneRaw, target.country),
      email: String(pick(p, 'email', 'emails.0') || ''),
      listing_url: String(pick(p, 'url', 'placeUrl', 'googleMapsUrl') || ''),
      social_profiles: collectSocials(p),

      rating: Number(pick(p, 'totalScore', 'rating')) || null,
      review_count: Number(pick(p, 'reviewsCount', 'userRatingCount', 'reviews')) || 0,
      price_level: String(pick(p, 'price', 'priceLevel') || ''),
      permanently_closed: false,
      temporarily_closed: Boolean(pick(p, 'temporarilyClosed') === true),

      // What the SOURCE said. Stage A decides what it means; this node does
      // not classify, it only records. Keeping the two separate is what lets
      // the classifier be re-run over old rows when its rules change.
      source_website_raw: String(pick(p, 'website', 'webSite', 'url_website') || ''),

      raw: p,
      source: 'apify:google-maps-extractor',
    },
  });
}

if (!out.length) {
  throw new Error(
    `All ${rows.length} Apify rows were discarded: ${skippedNoId} had no place id or name, ` +
    `${skippedClosed} were permanently closed. Nothing was stored.`
  );
}

return out;

// CH-01, node: "What did we find?"
// Mode: Run Once for All Items
//
// Builds the Telegram line and the numbers the next node writes back.
//
// The distinction that matters here is NEW versus ALREADY KNOWN. The upsert
// returns `inserted` (from xmax = 0) precisely so this can be honest. A report
// that says "50 businesses found" every morning when 48 of them were found
// last week is a report that stops being read by Friday - and then the morning
// it says something real, nobody notices.

const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);
const brake = $('BRAKE: can we afford this run?').first().json;

const total = rows.length;
const inserted = rows.filter((r) => r.inserted === true).length;
const known = total - inserted;

// Of the already-known rows, how many are still waiting on CH-02? Useful
// because a growing backlog here is the first sign CH-02 has stopped running,
// and that is invisible from CH-02's own output - a workflow that is not
// running produces no report at all.
const pending = rows.filter((r) => r.website_status === 'PENDING').length;

const where = [brake.city, brake.country].filter(Boolean).join(', ');

if (!total) {
  // Zero results is a real finding, not an error: it can genuinely mean every
  // business of this type in this city already has a website. Saying so
  // plainly beats an empty message that reads as a broken workflow.
  return [{
    json: {
      target_id: brake.target_id,
      total: 0,
      message:
        `CH-01 ${brake.niche} / ${where}\n` +
        `No businesses without a website were returned.\n` +
        `Asked for up to ${brake.asked_for}. Either this market is saturated, ` +
        `or the search term "${brake.niche_query}" is wrong for it.`,
    },
  }];
}

const lines = [
  `CH-01 ${brake.niche} / ${where}`,
  `${inserted} new, ${known} already known (${total} returned)`,
  `${pending} now waiting on verification`,
];

if (brake.budget_remaining != null) {
  const left = brake.budget_remaining - total;
  // Says WHICH limit is binding. "Running low" is not actionable on its own -
  // raising our own cap and topping up the Apify plan are different jobs, and
  // doing the wrong one leaves the pipeline just as stopped.
  lines.push(`~${Math.max(0, left)} places left before ${brake.budget_binding} runs out` +
             (brake.credit_remaining_usd != null ? ` ($${brake.credit_remaining_usd} credit)` : ''));
  if (left < 100) {
    lines.push(brake.budget_binding === 'Apify credit'
      ? 'Apify credit is nearly gone. It resets on the 1st and does not roll over.'
      : 'Our own cap is nearly reached. Raise app_state.apify_spend.monthly_place_cap.');
  }
}

// A sample makes the report checkable at a glance. A number alone cannot be
// sanity-checked; three names can.
const sample = rows.filter((r) => r.inserted).slice(0, 3).map((r) => r.google_place_id);
if (sample.length) lines.push(`e.g. ${sample.join(', ')}`);

return [{
  json: {
    target_id: brake.target_id,
    total,
    inserted,
    known,
    pending,
    message: lines.join('\n'),
  },
}];
